using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakEqualOuter;
internal sealed class LowerDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Paid U and W masks in the lower sector", H("Physical construction"),
        Blocks(Paragraph(Text("Use the exact U mask t-1 and W mask r, with their complements paid from the same physical stock. If s=2 the banks are all X; complementary U plus selected W; selected U plus all V; complementary W. If s>=4 the selected W moves to the third bank. The terminal order is W,U,X,V. Insert fresh first at literal cut zero. The physical inventory, the native balance identities and all six lower regimes consume the twenty-two certificates; no arbitrary divisible bank or favorable-feasibility premise is used."))), []));
}
